<template>
  <section class="portal-section acompanhamento-page"><div class="portal-container acompanhamento-wrap">
    <div v-if="loading" class="acompanhamento-card state"><LoaderCircle class="spin" /> Carregando chamado...</div>
    <div v-else-if="erro" class="acompanhamento-card state error"><CircleAlert /> {{ erro }}<RouterLink to="/atendimento">Abrir novo chamado</RouterLink></div>
    <template v-else>
      <section class="acompanhamento-card">
        <span class="portal-overline">Acompanhamento de chamado</span><div class="head"><div><h1>{{ chamado.protocolo }}</h1><p>{{ chamado.tipo_demanda }}</p></div><span :class="['status', chamado.status]">{{ statusLabel }}</span></div>
        <p class="descricao">{{ chamado.descricao }}</p><div class="timeline"><div :class="{ done: true }"><i>1</i><span>Chamado<br><small>registrado</small></span></div><div :class="{ done: ['orcamento_em_preparo','aguardando_autorizacao','autorizado'].includes(chamado.status) }"><i>2</i><span>Análise e<br><small>orçamento</small></span></div><div :class="{ done: ['aguardando_autorizacao','autorizado'].includes(chamado.status) }"><i>3</i><span>Autorização<br><small>do cliente</small></span></div><div :class="{ done: chamado.status === 'autorizado' }"><i>4</i><span>Contrato<br><small>disponível</small></span></div></div>
      </section>
      <section v-if="chamado.orcamento" class="acompanhamento-card proposal"><span class="portal-overline">Proposta disponível</span><h2>{{ chamado.orcamento.titulo }}</h2><p class="scope">{{ chamado.orcamento.descricao }}</p><div class="proposal-grid"><div><small>Valor do serviço</small><strong>R$ {{ moeda(chamado.orcamento.valor) }}</strong></div><div><small>Válido até</small><strong>{{ data(chamado.orcamento.validade) }}</strong></div></div>
        <template v-if="chamado.status === 'aguardando_autorizacao'"><div class="accept-box"><b>Autorizar este serviço</b><p>Ao confirmar, você declara que leu o escopo e autoriza a continuidade do atendimento. O sistema registrará o aceite e gerará o termo em PDF.</p><label>Nome de quem autoriza<input v-model.trim="nomeAceite" maxlength="200" placeholder="Digite seu nome completo" /></label><label class="check"><input v-model="aceite" type="checkbox" /> Li e concordo com o orçamento e o escopo descritos acima.</label><p v-if="erroAceite" class="accept-error">{{ erroAceite }}</p><button class="portal-button" :disabled="autorizando || !aceite || !nomeAceite" @click="autorizar">{{ autorizando ? 'Registrando aceite...' : 'Autorizar orçamento' }}</button></div></template>
        <template v-else-if="chamado.status === 'autorizado'"><div class="accepted"><CircleCheckBig /><div><b>Orçamento autorizado</b><p>O termo de prestação de serviços foi gerado e está disponível para download.</p></div></div><a v-if="chamado.contrato?.disponivel" class="portal-button" :href="contratoChamadoUrl(token)">Baixar contrato em PDF</a></template>
      </section>
      <section v-else class="acompanhamento-card pending"><Clock3 /><div><b>{{ statusLabel }}</b><p>A equipe está analisando sua solicitação. Quando o orçamento estiver pronto, esta página será atualizada.</p></div><button type="button" @click="carregar">Atualizar</button></section>
    </template>
  </div></section>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, RouterLink } from 'vue-router'
import { CircleAlert, CircleCheckBig, Clock3, LoaderCircle } from 'lucide-vue-next'
import { acompanharChamado, autorizarChamado, contratoChamadoUrl } from '@/services/portal'
const route = useRoute(); const token = computed(() => route.params.token); const chamado = ref(null); const loading = ref(true); const erro = ref(''); const nomeAceite = ref(''); const aceite = ref(false); const autorizando = ref(false); const erroAceite = ref('')
const labels = { recebido: 'Chamado recebido', em_triagem: 'Em triagem', orcamento_em_preparo: 'Orçamento em preparo', aguardando_autorizacao: 'Aguardando sua autorização', autorizado: 'Serviço autorizado', cancelado: 'Chamado cancelado' }
const statusLabel = computed(() => labels[chamado.value?.status] || 'Em atendimento')
const moeda = value => Number(value || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
const data = value => value ? new Date(`${value}T12:00:00`).toLocaleDateString('pt-BR') : 'Não informada'
async function carregar(){loading.value=true;erro.value='';try{chamado.value=await acompanharChamado(token.value)}catch(e){erro.value=e.response?.status===404?'Não encontramos este chamado. Confira o link recebido.':(e.response?.data?.message||'Não foi possível consultar o chamado agora.')}finally{loading.value=false}}
async function autorizar(){autorizando.value=true;erroAceite.value='';try{chamado.value=await autorizarChamado(token.value,{aceite:aceite.value,nome_aceite:nomeAceite.value})}catch(e){erroAceite.value=e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||'Não foi possível registrar sua autorização.'}finally{autorizando.value=false}}
onMounted(carregar)
</script>

<style scoped>
.acompanhamento-page{background:#f5faf6;min-height:calc(100vh - 74px)}.acompanhamento-wrap{max-width:850px;display:grid;gap:18px}.acompanhamento-card{background:#fff;border:1px solid #d7e5da;border-radius:20px;padding:clamp(20px,4vw,34px);box-shadow:0 12px 36px #173a2010}.state{display:flex;gap:12px;align-items:center;justify-content:center;min-height:220px;color:#35594a}.state.error{flex-direction:column;color:#b93030}.state a{color:#087e35;text-decoration:underline}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-top:8px}.head h1{font-size:1.8rem;color:#193a29;margin:0}.head p,.descricao,.scope{color:#526b5c}.status{display:inline-flex;border-radius:999px;padding:7px 11px;background:#edf2ee;color:#456050;font-size:.78rem;font-weight:800;text-align:center}.status.aguardando_autorizacao{background:#fff3d9;color:#9b6300}.status.autorizado{background:#dff8e7;color:#087735}.status.cancelado{background:#fee9e9;color:#b93232}.descricao{border-top:1px solid #e4ece6;margin-top:18px;padding-top:17px;white-space:pre-line}.timeline{display:flex;justify-content:space-between;gap:5px;margin-top:28px}.timeline>div{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;flex:1;color:#84948a;font-size:.75rem}.timeline>div:not(:last-child):after{content:'';position:absolute;height:2px;top:13px;left:61%;width:78%;background:#dbe6de}.timeline i{position:relative;z-index:1;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#edf3ee;font-style:normal;margin-bottom:7px}.timeline .done{color:#216e3c}.timeline .done i{background:#0aa044;color:#fff}.timeline .done:not(:last-child):after{background:#70c995}.proposal h2{color:#173d2a;margin:8px 0}.proposal-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0}.proposal-grid>div{padding:14px;border-radius:12px;background:#f2f8f3}.proposal-grid small{display:block;color:#63776b;font-size:.75rem}.proposal-grid strong{display:block;color:#0a7331;font-size:1.1rem;margin-top:3px}.accept-box{border-top:1px solid #dfeae2;padding-top:20px}.accept-box p{color:#5b7061;font-size:.9rem;line-height:1.5}.accept-box label:not(.check){display:block;margin:15px 0 10px;color:#244c36;font-size:.82rem;font-weight:800}.accept-box input[type=text],.accept-box input:not([type]){width:100%;padding:11px;border:1px solid #bcd3c2;border-radius:9px;margin-top:6px}.check{display:flex;gap:8px;color:#4e6757;font-size:.82rem;margin:14px 0}.accept-error{color:#bd3030!important}.accepted{display:flex;gap:12px;padding:16px;background:#edfbf1;border-radius:12px;margin:18px 0;color:#165b2c}.accepted svg{width:28px;flex:0 0 28px}.accepted p{margin:3px 0 0;color:#487458}.pending{display:flex;gap:13px;align-items:center}.pending>svg{color:#a16c00}.pending p{margin:3px 0;color:#66796c}.pending button{margin-left:auto;border:1px solid #a9c8b1;padding:8px 12px;border-radius:8px;color:#16733a;font-weight:800}@media(max-width:560px){.head{flex-direction:column}.timeline{overflow-x:auto;justify-content:flex-start;padding-bottom:7px}.timeline>div{min-width:105px}.proposal-grid{grid-template-columns:1fr}.pending{align-items:flex-start;flex-wrap:wrap}.pending button{margin-left:40px}.acompanhamento-card{border-radius:15px;padding:20px 16px}}
</style>
